def solution(names):
    answer = []
    for name in names:
        if name not in answer:
            answer.append(name)
    return answer

prac_2:
def solution(orders):
    best = None
    best_count = 0
    for menu in set(orders):
        c = 0
        for o in orders:
            if o == menu:
                c += 1
        if c > best_count or (c == best_count and menu < best):
            best, best_count = menu, c
    return best

prac_3:
def solution(visitors, k):
    best = 0
    for i in range(len(visitors) - k + 1):
        best = max(best, sum(visitors[i:i + k]))
    return best

