def solution(s):
    while '()' in s or '[]' in s or '{}' in s:
        s = s.replace('()', '').replace('[]', '').replace('{}', '')
    return s == ''

prac_5:
def solution(meetings):
    chosen = []
    for start, end in sorted(meetings, key=lambda m: m[1]):
        if all(start >= e or end <= s for s, e in chosen):
            chosen.append((start, end))
    return len(chosen)

prac_6:
def solution(maze):
    rows, cols = len(maze), len(maze[0])
    best = [-1]
    seen = set()
    def go(r, c, steps):
        if (r, c) == (rows - 1, cols - 1):
            if best[0] == -1 or steps < best[0]:
                best[0] = steps
            return
        for dr, dc in ((1, 0), (0, 1), (-1, 0), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] == '.' and (nr, nc) not in seen:
                seen.add((nr, nc))
                go(nr, nc, steps + 1)
                seen.remove((nr, nc))
    seen.add((0, 0))
    go(0, 0, 0)
    return best[0]

prac_7:
def solution(temps):
    answer = []
    for i in range(len(temps)):
        wait = 0
        for j in range(i + 1, len(temps)):
            if temps[j] > temps[i]:
                wait = j - i
                break
        answer.append(wait)
    return answer

prac_8:
def solution(n):
    if n <= 2:
        return n
    return (solution(n - 1) + solution(n - 2)) % 1_000_000_007
